from __future__ import annotations
import argparse
from .common import record, run_purpose

PURPOSE = 'performance-analysis'
CATALOG = [{'id': 'perf-regex-backtracking', 'concept': 'regex-catastrophic-backtracking', 'domain': 'software-engineering', 'subdomain': 'text-processing', 'difficulty': 'advanced', 'question': 'Request latency explodes for certain long input strings handled by a backtracking regular-expression engine, while normal inputs are fast. Give a measurement plan for catastrophic backtracking.', 'answer': "Capture the exact slow inputs and measure runtime as input length increases. Profile CPU stacks to confirm time is spent exploring the regex engine's backtracking paths. Compare the original expression with a structurally safer equivalent, an engine with guaranteed linear-time behavior where applicable, or explicit parsing. A superlinear/exponential curve tied to ambiguous nested quantifiers is strong evidence. Add input-length limits and regression cases because average production strings can hide the pathological tail.", 'verification_details': 'Must use adversarial input scaling plus profiling, connect the growth to backtracking structure, and test a safer expression/engine rather than relying on average latency.', 'tags': ['regex', 'backtracking', 'latency', 'profiling'], 'verification_method': 'rubric'}, {'id': 'perf-writev-batching', 'concept': 'writev-syscall-batching', 'domain': 'systems-programming', 'subdomain': 'io-performance', 'difficulty': 'advanced', 'question': 'A server sends many tiny adjacent buffers with one `write()` syscall per buffer. CPU profiles show substantial syscall overhead. Evaluate whether `writev()` batching could help.', 'answer': 'Measure messages/second, bytes/second, syscall rate, CPU time in kernel entry/exit, and latency before changing the code. Then batch compatible buffers into bounded `writev()` calls and rerun with the same workload. Improvement is supported if syscall count and CPU time fall without unacceptable batching latency or larger temporary queues. The implementation must still handle partial vectored writes correctly; batching is not permission to assume the entire iovec was consumed.', 'verification_details': 'Must compare syscall rate/CPU and latency before/after bounded writev batching and explicitly retain correct partial-write handling.', 'tags': ['writev', 'syscall', 'batching', 'io'], 'verification_method': 'rubric'}, {'id': 'perf-runqueue-oversubscription', 'concept': 'cpu-runqueue-oversubscription', 'domain': 'operating-systems', 'subdomain': 'scheduler', 'difficulty': 'advanced', 'question': 'A CPU-bound service has 4x more runnable worker threads than logical CPUs. Throughput no longer improves, but context switches and tail latency rise. Analyze scheduler oversubscription.', 'answer': 'Measure runnable-queue length, context-switch rate, CPU utilization, per-thread run/wait time, migrations, and throughput across worker counts. For pure CPU-bound independent work, once cores are saturated, extra runnable workers mainly compete for the same execution slots and add scheduling/cache costs. Sweep worker count around the CPU count and NUMA topology. The optimal number can differ when tasks block, so the conclusion must come from workload-specific scaling, not a rule that worker count always equals core count.', 'verification_details': 'Must correlate excessive runnable workers with context-switch/run-queue cost, sweep concurrency, and state the distinction between CPU-bound and blocking workloads.', 'tags': ['scheduler', 'runqueue', 'oversubscription', 'threads'], 'verification_method': 'rubric'}, {'id': 'perf-branch-mispredict', 'concept': 'branch-mispredict-hot-loop', 'domain': 'computer-architecture', 'subdomain': 'branch-prediction', 'difficulty': 'expert', 'question': 'A hot loop contains a data-dependent branch that is close to 50/50 random. CPI is high even though cache-miss rates are low. Determine whether branch misprediction is the bottleneck.', 'answer': 'Measure retired branches, branch misses/mispredict rate, cycles, instructions, and front-end/backend stall indicators with hardware counters. Compare against a semantically equivalent branchless/vectorized formulation on the same dataset. If mispredict penalties account for a substantial share of cycles and the branchless version improves throughput without increasing other bottlenecks excessively, the branch is causal. Also test datasets with predictable branch distributions to separate predictor behavior from unrelated loop cost.', 'verification_details': 'Must use branch/mispredict and cycle evidence, compare a controlled alternative, and vary predictability to establish causality.', 'tags': ['branch-prediction', 'cpi', 'performance-counters', 'branchless'], 'verification_method': 'rubric'}, {'id': 'perf-cache-conflict', 'concept': 'cache-set-conflict-thrashing', 'domain': 'computer-architecture', 'subdomain': 'cache', 'difficulty': 'expert', 'question': 'Two arrays fit comfortably within the nominal last-level cache capacity, yet alternating accesses to them cause unexpectedly high miss rates. How would you test for cache-set conflict rather than total-capacity pressure?', 'answer': 'Vary alignment, base offsets, stride, and array placement while holding total bytes constant. Inspect cache misses and, if available, set/slice-related counters. Conflict thrashing is supported when small address-layout changes that alter cache-set mapping sharply reduce misses even though working-set size is unchanged. Compare with a layout using padding or different strides. Nominal cache capacity alone is insufficient because associativity and indexing determine how many competing lines can occupy one set.', 'verification_details': 'Must hold working-set size constant while changing mapping/alignment/stride, use cache-miss evidence, and explain associativity/set conflicts.', 'tags': ['cache', 'associativity', 'conflict-miss', 'alignment'], 'verification_method': 'rubric'}, {'id': 'perf-readahead-random', 'concept': 'readahead-random-io-mismatch', 'domain': 'linux-infrastructure', 'subdomain': 'storage', 'difficulty': 'advanced', 'question': 'A storage workload performs sparse random reads, but Linux readahead causes much more device traffic than the application consumes. Analyze whether readahead is hurting performance.', 'answer': 'Compare application bytes requested with block-device bytes read, cache hit behavior, latency, and queue depth. Run controlled trials with the relevant file-access hints/readahead settings reduced or adjusted. If device traffic and cache pollution fall while useful-read latency/throughput improves, aggressive readahead was mismatched to the access pattern. Avoid globally disabling readahead based on one workload because sequential workloads benefit from it.', 'verification_details': 'Must compare useful versus physical bytes, test readahead policy under the same workload, identify cache/device amplification, and avoid a global one-size-fits-all conclusion.', 'tags': ['linux', 'readahead', 'storage', 'random-io'], 'verification_method': 'rubric'}, {'id': 'perf-nagle-delayed-ack', 'concept': 'nagle-delayed-ack-small-rpc', 'domain': 'networking', 'subdomain': 'tcp-latency', 'difficulty': 'advanced', 'question': 'A request/response protocol sends very small TCP writes and sometimes sees tens of milliseconds of extra latency with no packet loss. Analyze whether Nagle/delayed-ACK interaction is involved.', 'answer': 'Capture packet timing and write boundaries. Look for a small unacknowledged segment followed by the sender holding another tiny write while the receiver delays its ACK. Compare with application-level batching and, where appropriate, a controlled `TCP_NODELAY` trial. Improvement under the same workload supports the hypothesis. Do not disable Nagle universally: it trades small-write latency against packet efficiency, and application buffering may be the better fix.', 'verification_details': 'Must use packet/write timing, identify the small-write/ACK delay interaction, test a controlled alternative, and state the packet-efficiency tradeoff.', 'tags': ['tcp', 'nagle', 'delayed-ack', 'latency'], 'verification_method': 'rubric'}, {'id': 'perf-fanout-tail', 'concept': 'fanout-tail-latency-amplification', 'domain': 'distributed-systems', 'subdomain': 'latency', 'difficulty': 'advanced', 'question': 'One frontend request fans out to 100 independent shards and waits for every response. Individual shard p99 latency is acceptable, but frontend p99 is poor. Analyze the tail-amplification effect.', 'answer': 'The frontend observes the maximum of many shard latencies, so the probability that at least one shard lands in its slow tail grows with fan-out. Measure the distribution of per-shard latency and the maximum/completion distribution as fan-out changes. Mitigations depend on semantics: reduce fan-out, use hierarchical aggregation, replicate/hedge carefully, cache, or return partial/threshold results where allowed. Improving only mean shard latency can leave the maximum tail mostly unchanged.', 'verification_details': 'Must explain maximum-of-many tail amplification, measure frontend completion versus fan-out/per-shard distributions, and propose semantics-aware mitigation.', 'tags': ['distributed', 'fanout', 'tail-latency', 'p99'], 'verification_method': 'rubric'}, {'id': 'perf-kernel-launch-overhead', 'concept': 'gpu-kernel-launch-overhead', 'domain': 'compute-model-infrastructure', 'subdomain': 'gpu-performance', 'difficulty': 'intermediate', 'question': 'A GPU workload launches thousands of tiny kernels. GPU utilization is low even though the arithmetic work would fit easily on the device. Determine whether launch overhead is dominating.', 'answer': 'Use a GPU timeline to measure kernel duration, gaps, and CPU-side launch activity. Sum useful kernel time versus scheduling/launch gaps and compare with a fused or batched implementation that performs more work per launch. If total runtime drops substantially while arithmetic is unchanged and gaps shrink, launch overhead was significant. Also inspect synchronization between launches because tiny kernels plus unnecessary waits can look similar.', 'verification_details': 'Must use a timeline, compare useful kernel duration with launch/gap cost, test fusion/batching, and distinguish launch overhead from explicit synchronization.', 'tags': ['gpu', 'kernel-launch', 'fusion', 'profiling'], 'verification_method': 'rubric'}, {'id': 'perf-pinned-transfer', 'concept': 'pinned-memory-h2d-transfer', 'domain': 'compute-model-infrastructure', 'subdomain': 'gpu-transfer', 'difficulty': 'expert', 'question': 'Host-to-GPU copies are slower than expected and cannot overlap reliably with compute. Evaluate whether pageable host memory is limiting transfer behavior.', 'answer': 'Benchmark transfer bandwidth/latency for identical buffer sizes using pageable and pinned host allocations, then inspect a timeline for copy/compute overlap. Asynchronous DMA generally requires page-locked host memory so the device can transfer from stable physical pages without an intermediate staging step. If pinned buffers improve sustained bandwidth/overlap, the hypothesis is supported. Keep pinned allocations bounded because excessive page locking reduces memory-management flexibility and can harm the system.', 'verification_details': 'Must compare pageable versus pinned transfer behavior, inspect overlap, explain DMA/staging implications, and note that pinned memory should be bounded.', 'tags': ['gpu', 'pinned-memory', 'dma', 'transfer'], 'verification_method': 'rubric'}]

FAMILIES = [
    {
        "id": x["id"],
        "concept": x["concept"],
        "domain": x["domain"],
    }
    for x in CATALOG
]
BY_ID = {x["id"]: x for x in CATALOG}

def build(family, rng, rid, _difficulty):
    x = BY_ID[family["id"]]
    return record(
        rid,
        x["domain"],
        x["subdomain"],
        PURPOSE,
        x["difficulty"],
        x["question"],
        x["answer"],
        x["verification_method"],
        x["verification_details"],
        x["tags"],
    )

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--records", type=int, default=len(FAMILIES))
    ap.add_argument("--seed", type=int, default=20260914)
    args = ap.parse_args()
    run_purpose(
        purpose=PURPOSE,
        families=FAMILIES,
        build=build,
        records_requested=args.records,
        seed=args.seed,
    )

if __name__ == "__main__":
    main()
